'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ImageIcon,
  PaperclipIcon,
  SendIcon,
  ThumbsUpIcon,
  TriangleAlertIcon,
  XIcon,
  LightbulbIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { RadioGroup, RadioGroupItem } from '@/registry/ndeko/ui/radio-group';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import {
  ActionButton,
  useTimedAction,
  type ActionLabels,
} from './_parts/action-button';
import { ChoiceSegments, type SegmentOption } from './_parts/choice-segments';
import {
  ModalCloseButton,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { chipVariantsOf, morphOf } from './_parts/motion';
import { CURRENT_USER, WORKSPACE_NAME, firstNameOf } from './_parts/people';
import { Swap } from './_parts/swap';

type FeedbackKind = 'idea' | 'problem' | 'praise';

type Attachment = { name: string; size: string };

const KINDS: SegmentOption<FeedbackKind>[] = [
  { value: 'idea', label: 'Idea', icon: LightbulbIcon },
  { value: 'problem', label: 'Problem', icon: TriangleAlertIcon },
  { value: 'praise', label: 'Praise', icon: ThumbsUpIcon },
];

const PLACEHOLDER: Record<FeedbackKind, string> = {
  idea: 'Describe the idea and the problem it would solve',
  problem: 'What you did, what happened and what you expected',
  praise: 'What worked well, and where',
};

const THANKS_LINE: Record<FeedbackKind, string> = {
  idea: 'The product team reads every idea and links it to the roadmap once it is planned',
  problem: `We reply by e-mail within two working days, at ${CURRENT_USER.email}`,
  praise: 'It goes straight to the people who built that part',
};

const SCALE = [1, 2, 3, 4, 5];

const FIRST_RATING = 4;

const MESSAGE_LIMIT = 500;

const KILOBYTE = 1024;

const MEGABYTE = KILOBYTE * KILOBYTE;

const SEND_LABELS: ActionLabels = {
  idle: 'Send feedback',
  working: 'Sending',
  done: 'Sent',
};

const STEP_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const STEP_VARIANTS: Variants = {
  hidden: { opacity: 0, filter: 'blur(2px)', transition: STEP_TRANSITION },
  shown: { opacity: 1, filter: 'blur(0px)', transition: STEP_TRANSITION },
};

const STEP_FADE: Variants = {
  hidden: { opacity: 0, transition: STEP_TRANSITION },
  shown: { opacity: 1, transition: STEP_TRANSITION },
};

const SCALE_SEGMENT = [
  'relative isolate flex h-7 flex-1 cursor-pointer items-center justify-center rounded-full text-[13px] font-medium tabular-nums text-muted-foreground',
  'transition-colors duration-150 hover:text-foreground has-data-checked:text-foreground',
  'has-focus-visible:ring-[3px] has-focus-visible:ring-ring/25',
].join(' ');

const SCALE_THUMB =
  'absolute inset-0 -z-10 rounded-full bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

function stepVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return STEP_FADE;
  }
  return STEP_VARIANTS;
}

function questionOf(rating: number) {
  if (rating <= 2) {
    return 'What got in your way';
  }
  if (rating === 3) {
    return 'What would make it work better for you';
  }
  return 'What do you rely on most';
}

function sizeLabelOf(bytes: number) {
  if (bytes < MEGABYTE) {
    const kilobytes = Math.max(1, Math.round(bytes / KILOBYTE));
    return `${kilobytes} KB`;
  }
  const megabytes = (bytes / MEGABYTE).toFixed(1);
  return `${megabytes} MB`;
}

function RatingScale({
  rating,
  labelId,
  onChange,
}: {
  rating: number;
  labelId: string;
  onChange: (rating: number) => void;
}) {
  const thumbId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const thumbTransition = morphOf(shouldReduceMotion);

  function changeRating(value: unknown) {
    const nextRating = Number(value);
    const isOnScale = SCALE.includes(nextRating);
    if (isOnScale) {
      onChange(nextRating);
    }
  }

  return (
    <div className='flex items-center gap-3'>
      <span className='text-muted-foreground shrink-0 text-xs'>Not well</span>
      <RadioGroup
        aria-labelledby={labelId}
        value={String(rating)}
        onValueChange={changeRating}
        className='bg-foreground/[0.05] flex flex-1 gap-0.5 rounded-full p-0.5'
      >
        {SCALE.map((step) => {
          const isPicked = step === rating;

          return (
            <label key={step} className={SCALE_SEGMENT}>
              <RadioGroupItem value={String(step)} className='sr-only' />
              {isPicked && (
                <motion.span
                  layoutId={thumbId}
                  transition={thumbTransition}
                  aria-hidden='true'
                  className={SCALE_THUMB}
                />
              )}
              {step}
            </label>
          );
        })}
      </RadioGroup>
      <span className='text-muted-foreground shrink-0 text-xs'>Very well</span>
    </div>
  );
}

function AttachSlot({
  attachment,
  onAttach,
  onRemove,
}: {
  attachment: Attachment | null;
  onAttach: (attachment: Attachment) => void;
  onRemove: () => void;
}) {
  const inputId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = chipVariantsOf(shouldReduceMotion);

  function pickFile(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) {
      return;
    }
    onAttach({ name: file.name, size: sizeLabelOf(file.size) });
  }

  return (
    <div className='relative h-11'>
      <AnimatePresence initial={false} mode='popLayout'>
        {attachment && (
          <motion.div
            key='file'
            variants={variants}
            initial='hidden'
            animate='shown'
            exit='hidden'
            className='bg-card hairline-ring ring-border flex h-11 items-center gap-2.5 rounded-lg pr-1.5 pl-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
          >
            <span className='keycap-3d text-muted-foreground flex size-7 shrink-0 items-center justify-center rounded-md'>
              <ImageIcon className='size-3.5' />
            </span>
            <span className='flex min-w-0 flex-1 flex-col'>
              <span className='truncate text-[13px] font-medium'>
                {attachment.name}
              </span>
              <span className='text-muted-foreground text-xs tabular-nums'>
                {attachment.size}
              </span>
            </span>
            <Button
              variant='ghost'
              size='icon-sm'
              aria-label={`Remove ${attachment.name}`}
              onClick={onRemove}
              className='text-muted-foreground'
            >
              <XIcon />
            </Button>
          </motion.div>
        )}
        {!attachment && (
          <motion.label
            key='slot'
            htmlFor={inputId}
            variants={variants}
            initial='hidden'
            animate='shown'
            exit='hidden'
            className='hairline-border border-foreground/20 text-muted-foreground hover:bg-foreground/[0.02] hover:text-foreground has-focus-visible:ring-ring/25 flex h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border-dashed text-[13px] transition-colors duration-150 has-focus-visible:ring-[3px]'
          >
            <PaperclipIcon className='size-4' />
            Attach a screenshot
            <span className='text-muted-foreground/80'>(optional)</span>
            <input
              id={inputId}
              type='file'
              accept='image/png,image/jpeg'
              onChange={pickFile}
              className='sr-only'
            />
          </motion.label>
        )}
      </AnimatePresence>
    </div>
  );
}

function FeedbackForm({
  kind,
  onKindChange,
  onSent,
}: {
  kind: FeedbackKind;
  onKindChange: (kind: FeedbackKind) => void;
  onSent: () => void;
}) {
  const [rating, setRating] = useState(FIRST_RATING);
  const [message, setMessage] = useState('');
  const [attachment, setAttachment] = useState<Attachment | null>({
    name: 'timesheet-export.png',
    size: '284 KB',
  });
  const { state, run } = useTimedAction();
  const scaleLabelId = useId();
  const messageId = useId();
  const countId = useId();
  const question = questionOf(rating);
  const hasMessage = message.trim().length > 0;
  const isIdle = state === 'idle';
  const isSendDisabled = isIdle && !hasMessage;

  function changeMessage(event: React.ChangeEvent<HTMLTextAreaElement>) {
    setMessage(event.target.value);
  }

  function removeAttachment() {
    setAttachment(null);
  }

  function send(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!hasMessage) {
      return;
    }
    run(onSent);
  }

  return (
    <form onSubmit={send} className='flex flex-col gap-5'>
      <ModalHeader>
        <ModalTitle>Send feedback</ModalTitle>
        <ModalDescription>
          {`It goes to the people who build ${WORKSPACE_NAME}; they read every message`}
        </ModalDescription>
      </ModalHeader>
      <ChoiceSegments
        label='Kind of feedback'
        value={kind}
        options={KINDS}
        onValueChange={onKindChange}
      />
      <div className='flex flex-col gap-2'>
        <span id={scaleLabelId} className='text-[13px] font-medium'>
          {`How well does ${WORKSPACE_NAME} work for you`}
        </span>
        <RatingScale
          rating={rating}
          labelId={scaleLabelId}
          onChange={setRating}
        />
      </div>
      <div className='flex flex-col gap-1.5'>
        <div className='flex items-baseline justify-between gap-3'>
          <label htmlFor={messageId} className='text-[13px] font-medium'>
            <Swap swapKey={question} kind='label'>
              {question}
            </Swap>
          </label>
          <span className='text-muted-foreground text-xs'>Required</span>
        </div>
        <Textarea
          id={messageId}
          required
          value={message}
          maxLength={MESSAGE_LIMIT}
          aria-describedby={countId}
          placeholder={PLACEHOLDER[kind]}
          onChange={changeMessage}
          className='min-h-24'
        />
        <p
          id={countId}
          className='text-muted-foreground self-end text-xs tabular-nums'
        >
          {`${message.length} of ${MESSAGE_LIMIT} characters`}
        </p>
      </div>
      <AttachSlot
        attachment={attachment}
        onAttach={setAttachment}
        onRemove={removeAttachment}
      />
      <ModalFooter>
        <ModalCloseButton type='button' variant='ghost'>
          Cancel
        </ModalCloseButton>
        <ActionButton
          type='submit'
          state={state}
          labels={SEND_LABELS}
          idleIcon={<SendIcon />}
          disabled={isSendDisabled}
        />
      </ModalFooter>
    </form>
  );
}

function ThanksStep({
  kind,
  onSendMore,
}: {
  kind: FeedbackKind;
  onSendMore: () => void;
}) {
  return (
    <div className='flex flex-col gap-5'>
      <ModalHeader className='items-start gap-3'>
        <StatusOrb tone='success' />
        <ModalTitle>{`Thanks, ${firstNameOf(CURRENT_USER)}`}</ModalTitle>
        <ModalDescription>{THANKS_LINE[kind]}</ModalDescription>
      </ModalHeader>
      <ModalFooter>
        <Button variant='ghost' onClick={onSendMore}>
          Send more feedback
        </Button>
        <ModalCloseButton variant='outline'>Close</ModalCloseButton>
      </ModalFooter>
    </div>
  );
}

function FeedbackContent() {
  const [kind, setKind] = useState<FeedbackKind>('idea');
  const [isSent, setIsSent] = useState(false);
  const [formKey, setFormKey] = useState(0);
  const shouldReduceMotion = usePrefersReducedMotion();
  const stepVariants = stepVariantsOf(shouldReduceMotion);

  function markSent() {
    setIsSent(true);
  }

  function sendMore() {
    setFormKey((previous) => previous + 1);
    setIsSent(false);
  }

  return (
    <div className='relative'>
      <AnimatePresence initial={false} mode='popLayout'>
        {!isSent && (
          <motion.div
            key={`form-${formKey}`}
            variants={stepVariants}
            initial='hidden'
            animate='shown'
            exit='hidden'
          >
            <FeedbackForm
              kind={kind}
              onKindChange={setKind}
              onSent={markSent}
            />
          </motion.div>
        )}
        {isSent && (
          <motion.div
            key='thanks'
            variants={stepVariants}
            initial='hidden'
            animate='shown'
            exit='hidden'
          >
            <ThanksStep kind={kind} onSendMore={sendMore} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default function Modal09() {
  return (
    <ModalPreview triggerLabel='Open send feedback' size='md'>
      <FeedbackContent />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import type { Icon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

export type SegmentOption<Value extends string> = {
  value: Value;
  label: string;
  icon?: Icon;
};

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

type ChoiceSegmentsProps<Value extends string> = {
  value: Value;
  options: SegmentOption<Value>[];
  onValueChange: (value: Value) => void;
  /** Names the group for screen readers when no visible label points at it. */
  label: string;
  className?: string;
};

/** One choice out of a few on a segmented track: a raised thumb travels to the picked segment. */
export function ChoiceSegments<Value extends string>({
  value,
  options,
  onValueChange,
  label,
  className,
}: ChoiceSegmentsProps<Value>) {
  const pressedValues = [value];

  function changeValue(nextValues: unknown[]) {
    const [nextValue] = nextValues;
    const option = options.find((candidate) => candidate.value === nextValue);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <ToggleGroup
      aria-label={label}
      value={pressedValues}
      onValueChange={changeValue}
      travel
      size='sm'
      indicatorClassName={THUMB}
      className={cn('bg-foreground/[0.05] w-full rounded-lg p-0.5', className)}
    >
      {options.map((option) => {
        const OptionGlyph = option.icon;

        return (
          <ToggleGroupItem
            key={option.value}
            value={option.value}
            className='flex-1 rounded-md'
          >
            {OptionGlyph && <OptionGlyph />}
            {option.label}
          </ToggleGroupItem>
        );
      })}
    </ToggleGroup>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

